//! Conformance: `kte-unicode` must match every expected value in the shared
//! corpus, which is generated by the independent reference implementation in
//! `tools/spec-ref`.

use kte_unicode::{
    CellModel, LegacyWidths, cluster_width, clusters, half_units, is_single_cluster, str_width,
};
use serde_json::Value;

fn corpus() -> Vec<Value> {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/corpus/khmer_corpus.json"
    );
    let text = std::fs::read_to_string(path).expect("read corpus");
    serde_json::from_str(&text).expect("parse corpus")
}

#[test]
fn corpus_conformance() {
    let cases = corpus();
    assert!(cases.len() >= 30, "corpus unexpectedly small");
    let mut failures = Vec::new();

    for case in &cases {
        let id = case["id"].as_str().unwrap();
        let text = case["text"].as_str().unwrap();
        let expected = &case["expected"];

        let got: Vec<&str> = clusters(text).map(|(_, c)| c).collect();
        let want: Vec<&str> = expected["clusters"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap())
            .collect();
        if got != want {
            failures.push(format!("{id}: clusters {got:?} != {want:?}"));
            continue;
        }

        for (cluster, want_h) in got.iter().zip(expected["half_units"].as_array().unwrap()) {
            let want_h = want_h.as_u64().map(|h| h as u32);
            if half_units(cluster) != want_h {
                failures.push(format!(
                    "{id}: half_units({cluster:?}) = {:?}, expected {want_h:?}",
                    half_units(cluster)
                ));
            }
        }

        // Legacy cells: grow a cell while it stays one cell, as the terminal does.
        let glibc = CellModel::Legacy(LegacyWidths::Glibc);
        let mut cells: Vec<String> = Vec::new();
        for c in text.chars() {
            match cells.last_mut() {
                Some(cell) if is_single_cluster(&format!("{cell}{c}"), glibc) => cell.push(c),
                _ => cells.push(c.to_string()),
            }
        }
        let want_cells = expected["legacy_glibc_cells"].as_u64().unwrap() as usize;
        if cells.len() != want_cells {
            failures.push(format!(
                "{id}: {} legacy cells, expected {want_cells}",
                cells.len()
            ));
        }

        for (model, key) in [
            (CellModel::Wide, "wide"),
            (CellModel::Compact, "compact"),
            (CellModel::Legacy(LegacyWidths::Glibc), "legacy_glibc"),
            (CellModel::Legacy(LegacyWidths::Apple), "legacy_apple"),
        ] {
            let want = expected[key].as_u64().unwrap() as usize;
            let got = str_width(text, model);
            if got != want {
                failures.push(format!("{id}: {key} width {got} != {want}"));
            }
            let sum: usize = clusters(text).map(|(_, c)| cluster_width(c, model)).sum();
            assert_eq!(
                sum, got,
                "{id}: str_width must equal the sum of cluster widths"
            );
        }
    }

    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
